/* IT Budget Dashboard: vanilla JS, no dependencies, works from file://.
 *
 * Data comes from window.BUDGET_DATA (site/data.js, generated by scripts/build_data.py).
 * Layout follows "summary → detail": headline numbers, then breakdowns, renewals,
 * phasing, year-over-year bridge, line items and data quality. One set of global
 * filters (kept in the URL hash so views can be bookmarked/shared) drives every view.
 */
(function () {
  'use strict';

  const DATA = window.BUDGET_DATA;
  const LOCALE = 'en-GB';
  const UNASSIGNED = '(unassigned)';
  const SVGNS = 'http://www.w3.org/2000/svg';
  const CATEGORIES = ['Licence', 'Service', 'Contract'];
  const CAT_VAR = { Licence: '--cat-licence', Service: '--cat-service', Contract: '--cat-contract' };
  const URGENCY = [
    { key: 'passed', label: 'Notice deadline passed', max: -1, color: '--urg-passed' },
    { key: 'd30', label: '≤ 30 days', max: 30, color: '--urg-30' },
    { key: 'd60', label: '31–60 days', max: 60, color: '--urg-60' },
    { key: 'd90', label: '61–90 days', max: 90, color: '--urg-90' },
    { key: 'later', label: '> 90 days', max: Infinity, color: '--urg-later' },
  ];
  const FILTERS = [
    ['category', 'Category'], ['cost_pool', 'Cost pool'], ['tower', 'Tower'],
    ['cost_centre', 'Cost centre'], ['vendor', 'Vendor'], ['owner', 'Owner'],
  ];

  // ------------------------------------------------------------------ helpers

  const $ = (id) => document.getElementById(id);

  function make(ns, tag, attrs, children) {
    const el = ns ? document.createElementNS(ns, tag) : document.createElement(tag);
    for (const [k, v] of Object.entries(attrs || {})) {
      if (v == null || v === false) continue;
      if (k.startsWith('on')) el.addEventListener(k.slice(2), v);
      else if (k === 'text') el.textContent = v;
      else el.setAttribute(k, v === true ? '' : v);
    }
    for (const c of children.flat(Infinity)) {
      if (c == null || c === false) continue;
      el.append(c instanceof Node ? c : String(c));
    }
    return el;
  }
  const h = (tag, attrs, ...c) => make(null, tag, attrs, c);
  const s = (tag, attrs, ...c) => make(SVGNS, tag, attrs, c);

  if (!DATA || !Array.isArray(DATA.lines)) {
    document.body.replaceChildren(h('div', { class: 'no-data' },
      h('h1', {}, 'No budget data loaded'),
      h('p', {}, 'Build the data file first, then reload this page:'),
      h('pre', {}, 'python3 scripts/build_data.py data/sample-budget.xlsx')));
    return;
  }

  const META = DATA.meta;
  const YEAR = META.budget_year;
  let money, moneyCompact;
  try {
    money = new Intl.NumberFormat(LOCALE, { style: 'currency', currency: META.currency || 'EUR', maximumFractionDigits: 0 });
    moneyCompact = new Intl.NumberFormat(LOCALE, { style: 'currency', currency: META.currency || 'EUR', notation: 'compact', maximumFractionDigits: 1 });
  } catch (e) {
    money = new Intl.NumberFormat(LOCALE, { maximumFractionDigits: 0 });
    moneyCompact = new Intl.NumberFormat(LOCALE, { notation: 'compact', maximumFractionDigits: 1 });
  }
  const fmtMoney = (v) => (v == null ? '–' : money.format(v));
  const fmtCompact = (v) => (v == null ? '–' : moneyCompact.format(v));
  const fmtPct = (v, d = 0) => (v == null || !isFinite(v) ? '–' : (v * 100).toFixed(d) + '%');
  const fmtSignedPct = (v) => (v == null || !isFinite(v) ? '–' : (v > 0 ? '+' : '') + (v * 100).toFixed(1) + '%');
  const fmtSignedMoney = (v) => (v > 0 ? '+' : v < 0 ? '−' : '') + fmtCompact(Math.abs(v));
  const toDay = (iso) => Date.parse(iso + 'T00:00:00Z') / 864e5;
  const fromDay = (d) => new Date(d * 864e5);
  const fmtDate = (iso) => (iso ? fromDay(toDay(iso)).toLocaleDateString(LOCALE, { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' }) : '–');
  const AS_OF = toDay(META.as_of);
  const sum = (arr, fn) => arr.reduce((a, x) => a + (fn(x) || 0), 0);
  const val = (line, field) => line[field] || UNASSIGNED;
  const cssVar = (name) => `var(${name})`;
  const catColor = (cat) => cssVar(CAT_VAR[cat] || '--cat-other');

  function groupSum(lines, field) {
    const m = new Map();
    for (const l of lines) {
      const k = val(l, field);
      const g = m.get(k) || { key: k, value: 0, count: 0 };
      g.value += l.annual_budget; g.count += 1;
      m.set(k, g);
    }
    return [...m.values()].sort((a, b) => b.value - a.value || a.key.localeCompare(b.key));
  }

  function urgencyOf(line) {
    if (!line.notice_deadline || !(line.annual_budget > 0)) return null;
    const days = toDay(line.notice_deadline) - AS_OF;
    const u = days < 0 ? URGENCY[0] : URGENCY.slice(1).find((x) => days <= x.max);
    return { ...u, days: Math.round(days) };
  }

  function niceTicks(max, n = 4) {
    if (!(max > 0)) return { max: 1, ticks: [0, 1] };
    const raw = max / n;
    const mag = Math.pow(10, Math.floor(Math.log10(raw)));
    const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((x) => x >= raw);
    const top = Math.ceil(max / step - 1e-9) * step;
    const ticks = [];
    for (let v = 0; v <= top + step / 2; v += step) ticks.push(v);
    return { max: top, ticks };
  }

  // tooltip shared by all SVG charts
  const tip = $('tooltip');
  function showTip(target, parts) {
    tip.replaceChildren(...parts.map((p, i) => (i === 0 ? h('b', {}, p) : h('div', {}, p))));
    tip.hidden = false;
    const r = target.getBoundingClientRect();
    const tw = tip.offsetWidth, th = tip.offsetHeight;
    let x = r.right + 10, y = r.top + r.height / 2 - th / 2;
    if (x + tw > innerWidth - 8) x = r.left - tw - 10;
    if (x < 8) x = Math.max(8, Math.min(innerWidth - tw - 8, r.left));
    y = Math.max(8, Math.min(innerHeight - th - 8, y));
    tip.style.left = x + 'px';
    tip.style.top = y + 'px';
  }
  const hideTip = () => { tip.hidden = true; };
  function withTip(el, partsFn) {
    el.addEventListener('mouseenter', () => showTip(el, partsFn()));
    el.addEventListener('focus', () => showTip(el, partsFn()));
    el.addEventListener('mouseleave', hideTip);
    el.addEventListener('blur', hideTip);
    return el;
  }
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') hideTip(); });
  addEventListener('scroll', hideTip, { passive: true });

  // ------------------------------------------------------------------ state & filters

  const state = { f: {}, q: '', sort: { key: 'annual_budget', dir: -1 } };

  function readHash() {
    const p = new URLSearchParams(location.hash.slice(1));
    for (const [k] of FILTERS) { const v = p.get(k); if (v) state.f[k] = v; }
    state.q = p.get('q') || '';
  }
  function writeHash() {
    const p = new URLSearchParams();
    for (const [k] of FILTERS) if (state.f[k]) p.set(k, state.f[k]);
    if (state.q) p.set('q', state.q);
    const str = p.toString();
    try { history.replaceState(null, '', str ? '#' + str : location.pathname + location.search); } catch (e) { /* ignore */ }
  }

  function matches(line) {
    for (const [k] of FILTERS) {
      const v = state.f[k];
      if (v && val(line, k) !== v) return false;
    }
    if (state.q) {
      const hay = [line.line_id, line.vendor, line.product_or_service, line.notes, line.owner, line.cost_centre, line.cost_pool]
        .join(' ').toLowerCase();
      if (!hay.includes(state.q.toLowerCase())) return false;
    }
    return true;
  }

  function setFilter(field, value) {
    if (!value || state.f[field] === value) delete state.f[field];
    else state.f[field] = value;
    render();
  }

  function buildFilterControls() {
    const grid = $('filter-grid');
    for (const [field, label] of FILTERS) {
      const values = [...new Set(DATA.lines.map((l) => val(l, field)))]
        .sort((a, b) => (a === UNASSIGNED) - (b === UNASSIGNED) || a.localeCompare(b));
      if (values.length === 1 && values[0] === UNASSIGNED) continue; // column not used in this file
      const sel = h('select', { id: 'filter-' + field, onchange: (e) => setFilter(field, e.target.value) },
        h('option', { value: '' }, 'All'),
        values.map((v) => h('option', { value: v }, v)));
      grid.append(h('label', {}, h('span', {}, label), sel));
    }
    let t;
    $('filter-q').addEventListener('input', (e) => {
      clearTimeout(t);
      t = setTimeout(() => { state.q = e.target.value.trim(); render(); }, 150);
    });
    $('filter-reset').addEventListener('click', () => { state.f = {}; state.q = ''; $('filter-q').value = ''; render(); });
  }

  function syncControls() {
    for (const [field] of FILTERS) {
      const sel = $('filter-' + field);
      if (sel) sel.value = state.f[field] || '';
    }
    if ($('filter-q').value.trim() !== state.q) $('filter-q').value = state.q;
    const chips = $('active-chips');
    chips.replaceChildren();
    for (const [field, label] of FILTERS) {
      if (!state.f[field]) continue;
      chips.append(h('button', { type: 'button', class: 'chip', title: 'Remove filter', onclick: () => setFilter(field, null) },
        label + ': ', h('b', {}, state.f[field]), ' ✕'));
    }
    if (state.q) {
      chips.append(h('button', { type: 'button', class: 'chip', onclick: () => { state.q = ''; render(); } },
        'Search: ', h('b', {}, state.q), ' ✕'));
    }
  }

  // ------------------------------------------------------------------ KPIs

  function computeBridge(lines) {
    const b = { prior: 0, added: 0, increases: 0, decreases: 0, removed: 0, next: 0, newCount: 0, removedCount: 0 };
    for (const l of lines) {
      const cur = l.annual_budget, prior = l.prior_year_budget;
      b.next += cur;
      if (prior == null) { b.added += cur; if (cur > 0) b.newCount++; continue; }
      b.prior += prior;
      if (cur === 0 && prior > 0) { b.removed += prior; b.removedCount++; }
      else if (cur > prior) b.increases += cur - prior;
      else b.decreases += prior - cur;
    }
    return b;
  }

  function kpi(label, value, detail, opts = {}) {
    return h('div', { class: 'kpi' + (opts.wide ? ' wide' : '') + (opts.alert ? ' alert' : ''), 'data-kpi': opts.id },
      h('div', { class: 'label' }, label),
      h('div', { class: 'value', 'data-value': opts.raw }, value),
      h('div', { class: 'detail' }, detail));
  }

  function renderKpis(lines) {
    const total = sum(lines, (l) => l.annual_budget);
    const active = lines.filter((l) => l.annual_budget > 0);
    const vendors = new Set(active.map((l) => l.vendor)).size;
    const b = computeBridge(lines);
    const delta = total - b.prior;
    const deltaPct = b.prior ? delta / b.prior : null;

    const cats = CATEGORIES.map((c) => ({ c, v: sum(lines.filter((l) => l.category === c), (l) => l.annual_budget) }));
    const mix = h('div', { class: 'kpi wide', 'data-kpi': 'mix' },
      h('div', { class: 'label' }, 'Split by category'),
      h('div', { class: 'stack', role: 'img', 'aria-label': cats.map((x) => `${x.c} ${fmtPct(total ? x.v / total : 0)}`).join(', ') },
        cats.map((x) => h('span', { style: `width:${total ? (x.v / total) * 100 : 0}%;background:${catColor(x.c)}`, title: `${x.c}: ${fmtMoney(x.v)}` }))),
      h('div', { class: 'stack-legend' }, cats.map((x) => h('span', {},
        h('span', { class: 'swatch sq', style: `background:${catColor(x.c)}` }),
        `${x.c}s `, h('b', {}, fmtCompact(x.v)), ` (${fmtPct(total ? x.v / total : 0)})`))));

    const due = active.map((l) => ({ l, u: urgencyOf(l) })).filter((x) => x.u && x.u.max <= 90);
    const passed = due.filter((x) => x.u.key === 'passed').length;
    const unowned = active.filter((l) => !l.owner);
    const unownedV = sum(unowned, (l) => l.annual_budget);

    const changeEl = h('span', { class: delta > 0 ? 'up' : delta < 0 ? 'down' : '' },
      (delta > 0 ? '▲ ' : delta < 0 ? '▼ ' : '') + fmtSignedPct(deltaPct));

    $('kpis').replaceChildren(
      kpi(`Total budget FY${YEAR}`, fmtCompact(total), `${fmtMoney(total)} · ${active.length} active lines · ${vendors} vendors`, { raw: total, id: 'total' }),
      h('div', { class: 'kpi', 'data-kpi': 'change' },
        h('div', { class: 'label' }, 'Change vs prior-year budget'),
        h('div', { class: 'value' }, changeEl),
        h('div', { class: 'detail' }, b.prior ? `${fmtSignedMoney(delta)} vs ${fmtCompact(b.prior)}` : 'No prior-year figures')),
      mix,
      h('div', { class: 'kpi' + (passed ? ' alert' : ''), 'data-kpi': 'renewals' },
        h('div', { class: 'label' }, 'Notice deadlines in next 90 days'),
        h('div', { class: 'value' }, String(due.length)),
        h('div', { class: 'detail' }, `${fmtCompact(sum(due, (x) => x.l.annual_budget))} of contracts`,
          passed ? h('span', {}, ' · ', h('b', {}, `${passed} already passed`)) : null)),
      h('div', { class: 'kpi', 'data-kpi': 'unowned' },
        h('div', { class: 'label' }, 'Budget with no owner'),
        h('div', { class: 'value' }, fmtPct(total ? unownedV / total : 0, 1)),
        h('div', { class: 'detail' }, `${fmtCompact(unownedV)} across ${unowned.length} lines `,
          unowned.length && state.f.owner !== UNASSIGNED
            ? h('button', { type: 'button', class: 'btn-secondary', style: 'padding:0 8px;font-size:.75rem', onclick: () => setFilter('owner', UNASSIGNED) }, 'Show')
            : null)),
    );
  }

  // ------------------------------------------------------------------ bar lists

  function hbars(container, items, { field, total, limit, color } = {}) {
    container.replaceChildren();
    if (!items.length || !total) { container.append(h('div', { class: 'empty' }, 'No matching budget')); return; }
    const shown = limit ? items.slice(0, limit) : items;
    const rest = limit ? items.slice(limit) : [];
    const restV = sum(rest, (i) => i.value);
    const max = Math.max(restV, ...shown.map((i) => i.value)) || 1;
    const row = (name, value, clickable, extraColor) => {
      const active = clickable && state.f[field] === name;
      const kids = [
        h('span', { class: 'name', title: name }, name),
        h('span', { class: 'track' }, h('span', { class: 'fill', style: `width:${Math.max(0, (value / max) * 100)}%` + (extraColor ? `;background:${extraColor}` : '') })),
        h('span', { class: 'val' }, fmtMoney(value), h('small', {}, fmtPct(value / total))),
      ];
      return clickable
        ? h('button', { type: 'button', class: 'hbar' + (active ? ' active' : ''), 'aria-pressed': String(active), title: `Filter: ${name}`, onclick: () => setFilter(field, name) }, kids)
        : h('div', { class: 'hbar static' }, kids);
    };
    shown.forEach((i) => container.append(row(i.key, i.value, !!field, color ? color(i.key) : null)));
    if (rest.length) container.append(row(`All other (${rest.length})`, restV, false));
  }

  function renderBars(lines) {
    const total = sum(lines, (l) => l.annual_budget);
    hbars($('chart-pool'), groupSum(lines, 'cost_pool'), { field: 'cost_pool', total });
    const vendors = groupSum(lines, 'vendor').filter((v) => v.value > 0);
    hbars($('chart-vendor'), vendors, { field: 'vendor', total, limit: 10 });
    const top = sum(vendors.slice(0, 10), (v) => v.value);
    $('vendor-concentration').textContent = vendors.length
      ? `Top ${Math.min(10, vendors.length)} of ${vendors.length} vendors = ${fmtPct(total ? top / total : 0)} of spend`
      : '';
    hbars($('chart-cc'), groupSum(lines, 'cost_centre'), { field: 'cost_centre', total });
    hbars($('chart-capex'), groupSum(lines, 'capex_opex'), { total });
    hbars($('chart-tower'), groupSum(lines, 'tower'), { field: 'tower', total });
  }

  // ------------------------------------------------------------------ renewals

  function renderTimeline(lines) {
    const wrap = $('chart-timeline');
    const pts = lines.filter((l) => l.renewal_date && l.annual_budget > 0).map((l) => ({ l, u: urgencyOf(l), d: toDay(l.renewal_date) }));
    $('urgency-legend').replaceChildren(...URGENCY.map((u) => h('span', {},
      h('span', { class: 'swatch', style: `background:${cssVar(u.color)}` }),
      `${u.label} (${pts.filter((p) => p.u && p.u.key === u.key).length})`)));
    wrap.replaceChildren();
    if (!pts.length) { wrap.append(h('div', { class: 'empty' }, 'No renewal dates in the filtered lines')); return; }

    const asOf = fromDay(AS_OF);
    const monthStart = (dt) => Date.UTC(dt.getUTCFullYear(), dt.getUTCMonth(), 1) / 864e5;
    const minD = Math.min(AS_OF, ...pts.map((p) => p.d));
    const maxD = Math.max(Date.UTC(YEAR + 1, 0, 1) / 864e5, ...pts.map((p) => p.d));
    const d0 = monthStart(fromDay(minD));
    const lastM = fromDay(maxD);
    const d1 = Date.UTC(lastM.getUTCFullYear(), lastM.getUTCMonth() + 1, 1) / 864e5;

    const W = 960, H = 250, ml = 76, mr = 16, mt = 26, mb = 26;
    const x = (d) => ml + ((d - d0) / (d1 - d0)) * (W - ml - mr);
    const lanes = CATEGORIES.filter((c) => pts.some((p) => p.l.category === c));
    const laneH = (H - mt - mb) / lanes.length;
    const laneY = (c) => mt + laneH * (lanes.indexOf(c) + 0.5);
    const maxV = Math.max(...pts.map((p) => p.l.annual_budget));
    const radius = (v) => 4 + 13 * Math.sqrt(v / maxV);

    const g = s('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img', 'aria-label': `Renewal timeline with ${pts.length} renewals` });
    // budget-year band
    const fy0 = Math.max(d0, Date.UTC(YEAR, 0, 1) / 864e5), fy1 = Math.min(d1, Date.UTC(YEAR + 1, 0, 1) / 864e5);
    if (fy1 > fy0) {
      g.append(s('rect', { x: x(fy0), y: mt - 18, width: x(fy1) - x(fy0), height: H - mt - mb + 18, style: 'fill:var(--surface-2)' }));
      g.append(s('text', { x: x(fy0) + 6, y: mt - 6 }, `FY${YEAR}`));
    }
    // month grid
    const months = [];
    for (let m = fromDay(d0); m.getTime() / 864e5 < d1; m = new Date(Date.UTC(m.getUTCFullYear(), m.getUTCMonth() + 1, 1))) months.push(m);
    const every = months.length > 20 ? 3 : months.length > 14 ? 2 : 1;
    months.forEach((m, i) => {
      const xx = x(m.getTime() / 864e5);
      g.append(s('line', { class: 'gridline', x1: xx, x2: xx, y1: mt, y2: H - mb }));
      if (i % every === 0) {
        g.append(s('text', { x: xx + 3, y: H - 8 }, m.toLocaleDateString(LOCALE, { month: 'short', timeZone: 'UTC' }) + (m.getUTCMonth() === 0 || i === 0 ? ' ' + String(m.getUTCFullYear()).slice(2) : '')));
      }
    });
    lanes.forEach((c) => {
      g.append(s('line', { class: 'axis', x1: ml, x2: W - mr, y1: laneY(c), y2: laneY(c) }));
      g.append(s('text', { x: 4, y: laneY(c) + 4 }, c + 's'));
    });
    // as-of line
    g.append(s('line', { class: 'today', x1: x(AS_OF), x2: x(AS_OF), y1: mt - 18, y2: H - mb }));
    g.append(s('text', { class: 'today-label', x: x(AS_OF) + 4, y: mt - 6 }, 'As of ' + asOf.toLocaleDateString(LOCALE, { day: 'numeric', month: 'short', timeZone: 'UTC' })));

    // place dots largest first, nudging vertically to avoid overlaps
    const placed = [];
    const offsets = [0, -1, 1, -2, 2, -3, 3].map((k) => k * Math.min(14, laneH / 7));
    pts.sort((a, b) => b.l.annual_budget - a.l.annual_budget).forEach((p) => {
      const cx = x(p.d), r = radius(p.l.annual_budget), base = laneY(p.l.category);
      let cy = base;
      for (const off of offsets) {
        cy = base + off;
        if (!placed.some((q) => Math.hypot(q.cx - cx, q.cy - cy) < q.r + r - 3)) break;
      }
      placed.push({ cx, cy, r });
      const l = p.l, u = p.u;
      const dot = s('circle', {
        class: 'dot', cx, cy, r, tabindex: 0, style: `fill:${cssVar(u ? u.color : '--urg-none')}`,
        'aria-label': `${l.vendor}, ${l.product_or_service}: renews ${fmtDate(l.renewal_date)}, ${fmtMoney(l.annual_budget)}`,
        onclick: () => setFilter('vendor', l.vendor),
      });
      withTip(dot, () => [
        `${l.vendor}: ${l.product_or_service}`,
        `${fmtMoney(l.annual_budget)} · ${l.category}`,
        `Renews ${fmtDate(l.renewal_date)}${l.auto_renew ? ' (auto-renews)' : l.auto_renew === false ? ' (no auto-renew)' : ''}`,
        l.notice_period_days != null
          ? `Notice by ${fmtDate(l.notice_deadline)} (${l.notice_period_days} days): ${u.days < 0 ? `${-u.days} days ago` : `in ${u.days} days`}`
          : 'Notice period unknown',
        `Owner: ${l.owner || UNASSIGNED}`,
        'Click to filter on this vendor',
      ]);
      g.append(dot);
    });
    wrap.append(g);
  }

  function renderRenewalTable(lines) {
    const rows = lines.map((l) => ({ l, u: urgencyOf(l) }))
      .filter((x) => x.u && x.u.max <= 90)
      .sort((a, b) => a.u.days - b.u.days || b.l.annual_budget - a.l.annual_budget);
    const t = $('table-renewals');
    t.replaceChildren(
      h('caption', { class: 'sub', style: 'text-align:left;caption-side:top' }, 'Contracts whose notice deadline has passed or falls within 90 days, most urgent first.'),
      h('thead', {}, h('tr', {}, ['Notice deadline', 'Days left', 'Vendor', 'Product / service', 'Budget', 'Renewal', 'Auto-renew', 'Owner']
        .map((c, i) => h('th', { class: i === 1 || i === 4 ? 'num' : null, scope: 'col' }, c)))),
      h('tbody', {}, rows.length ? rows.map(({ l, u }) => h('tr', {},
        h('td', {}, fmtDate(l.notice_deadline)),
        h('td', { class: 'num' }, h('span', { class: 'badge urg', style: `background:${cssVar(u.color)}`, title: u.label }, u.days < 0 ? `${-u.days} d overdue` : `${u.days} d`)),
        h('td', {}, l.vendor),
        h('td', {}, l.product_or_service),
        h('td', { class: 'num' }, fmtMoney(l.annual_budget)),
        h('td', {}, fmtDate(l.renewal_date)),
        h('td', {}, l.auto_renew == null ? '–' : l.auto_renew ? 'Yes' : 'No'),
        h('td', {}, l.owner || h('span', { class: 'badge warn' }, UNASSIGNED)),
      )) : h('tr', {}, h('td', { colspan: 8, class: 'empty' }, 'Nothing needs action in the next 90 days.'))),
    );
  }

  // ------------------------------------------------------------------ phasing

  function renderPhasing(lines) {
    const wrap = $('chart-phasing');
    wrap.replaceChildren();
    const total = sum(lines, (l) => l.annual_budget);
    const derived = sum(lines.filter((l) => l.monthly_derived), (l) => l.annual_budget);
    $('phasing-note').textContent = total
      ? `${fmtPct(derived / total)} of this budget has no monthly figures in the spreadsheet and is spread evenly over 12 months; the rest uses the phasing provided.`
      : '';
    $('category-legend').replaceChildren(...CATEGORIES.map((c) => h('span', {},
      h('span', { class: 'swatch sq', style: `background:${catColor(c)}` }), c + 's')));
    if (!total) { wrap.append(h('div', { class: 'empty' }, 'No matching budget')); return; }

    const byMonth = Array.from({ length: 12 }, (_, m) => CATEGORIES.map((c) =>
      sum(lines.filter((l) => l.category === c), (l) => (l.monthly || [])[m])));
    const totals = byMonth.map((m) => m.reduce((a, b) => a + b, 0));
    const { max, ticks } = niceTicks(Math.max(...totals) * 1.08);
    const W = 960, H = 270, ml = 70, mr = 12, mt = 20, mb = 26;
    const bw = (W - ml - mr) / 12;
    const y = (v) => H - mb - (v / max) * (H - mt - mb);
    const g = s('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img', 'aria-label': 'Monthly phasing by category' });
    ticks.forEach((t) => {
      g.append(s('line', { class: 'gridline', x1: ml, x2: W - mr, y1: y(t), y2: y(t) }));
      g.append(s('text', { x: ml - 6, y: y(t) + 4, 'text-anchor': 'end' }, fmtCompact(t)));
    });
    const monthName = (m) => new Date(Date.UTC(YEAR, m, 1)).toLocaleDateString(LOCALE, { month: 'short', timeZone: 'UTC' });
    byMonth.forEach((vals, m) => {
      let acc = 0;
      const x0 = ml + m * bw + bw * 0.15, w = bw * 0.7;
      vals.forEach((v, ci) => {
        if (v <= 0) return;
        const rect = s('rect', { x: x0, y: y(acc + v), width: w, height: Math.max(0, y(acc) - y(acc + v)), style: `fill:${catColor(CATEGORIES[ci])}`, tabindex: 0 });
        withTip(rect, () => [`${monthName(m)} ${YEAR}: ${CATEGORIES[ci]}s`, fmtMoney(v), `Month total ${fmtMoney(totals[m])}`]);
        g.append(rect);
        acc += v;
      });
      g.append(s('text', { class: 'bar-label', x: x0 + w / 2, y: y(totals[m]) - 5, 'text-anchor': 'middle' }, fmtCompact(totals[m])));
      g.append(s('text', { x: x0 + w / 2, y: H - 8, 'text-anchor': 'middle' }, monthName(m)));
    });
    g.append(s('line', { class: 'axis', x1: ml, x2: W - mr, y1: y(0), y2: y(0) }));
    wrap.append(g);
  }

  // ------------------------------------------------------------------ year-over-year bridge

  function renderBridge(lines) {
    const wrap = $('chart-bridge');
    wrap.replaceChildren();
    const b = computeBridge(lines);
    const noPrior = lines.filter((l) => l.prior_year_budget == null).length;
    $('bridge-note').textContent = b.prior
      ? `How the prior-year budget becomes the FY${YEAR} budget. Lines with no prior-year figure count as new (${b.newCount}); lines budgeted at 0 with a prior-year figure count as removed (${b.removedCount}).`
      : 'No prior-year figures in the filtered lines.';
    if (!b.prior && !b.next) return;

    const steps = [
      { label: 'Prior year', v: b.prior, total: true },
      { label: 'New lines', v: b.added },
      { label: 'Increases', v: b.increases },
      { label: 'Decreases', v: -b.decreases },
      { label: 'Removed', v: -b.removed },
      { label: `FY${YEAR}`, v: b.next, total: true },
    ];
    let acc = 0;
    steps.forEach((st) => {
      if (st.total) { st.from = 0; st.to = st.v; acc = st.v; } else { st.from = acc; st.to = acc + st.v; acc = st.to; }
    });
    const { max, ticks } = niceTicks(Math.max(...steps.map((st) => Math.max(st.from, st.to))) * 1.08);
    const W = 960, H = 270, ml = 70, mr = 12, mt = 20, mb = 26;
    const bw = (W - ml - mr) / steps.length;
    const y = (v) => H - mb - (v / max) * (H - mt - mb);
    const g = s('svg', { viewBox: `0 0 ${W} ${H}`, role: 'img', 'aria-label': 'Bridge from prior-year budget to budget-year total' });
    ticks.forEach((t) => {
      g.append(s('line', { class: 'gridline', x1: ml, x2: W - mr, y1: y(t), y2: y(t) }));
      g.append(s('text', { x: ml - 6, y: y(t) + 4, 'text-anchor': 'end' }, fmtCompact(t)));
    });
    steps.forEach((st, i) => {
      const x0 = ml + i * bw + bw * 0.2, w = bw * 0.6;
      const top = y(Math.max(st.from, st.to)), bottom = y(Math.min(st.from, st.to));
      const fill = st.total ? 'var(--bar)' : st.v >= 0 ? 'var(--bad)' : 'var(--good)';
      const rect = s('rect', { x: x0, y: top, width: w, height: Math.max(1, bottom - top), style: `fill:${fill}`, rx: 2, tabindex: 0 });
      withTip(rect, () => [st.label, st.total ? fmtMoney(st.v) : (st.v >= 0 ? '+' : '−') + fmtMoney(Math.abs(st.v))]);
      g.append(rect);
      g.append(s('text', { class: 'bar-label', x: x0 + w / 2, y: top - 5, 'text-anchor': 'middle' }, st.total ? fmtCompact(st.v) : fmtSignedMoney(st.v)));
      g.append(s('text', { x: x0 + w / 2, y: H - 8, 'text-anchor': 'middle' }, st.label));
      if (i < steps.length - 1) {
        g.append(s('line', { class: 'connector', x1: x0 + w, x2: x0 + bw, y1: y(st.to), y2: y(st.to) }));
      }
    });
    g.append(s('line', { class: 'axis', x1: ml, x2: W - mr, y1: y(0), y2: y(0) }));
    wrap.append(g);
    if (noPrior && b.prior) wrap.append(h('p', { class: 'sub', style: 'margin-top:8px' }, `${noPrior} filtered line(s) have no prior-year figure.`));
  }

  // ------------------------------------------------------------------ line items

  const COLS = [
    { key: 'line_id', label: 'ID' },
    { key: 'vendor', label: 'Vendor' },
    { key: 'product_or_service', label: 'Product / service' },
    { key: 'category', label: 'Category' },
    { key: 'cost_pool', label: 'Cost pool' },
    { key: 'cost_centre', label: 'Cost centre' },
    { key: 'owner', label: 'Owner' },
    { key: 'annual_budget', label: `FY${YEAR}`, num: true },
    { key: 'prior_year_budget', label: 'Prior year', num: true },
    { key: '_change', label: 'Change', num: true, get: (l) => (l.prior_year_budget ? (l.annual_budget - l.prior_year_budget) / l.prior_year_budget : null) },
    { key: 'renewal_date', label: 'Renewal' },
    { key: 'auto_renew', label: 'Auto-renew' },
  ];
  const colVal = (c, l) => (c.get ? c.get(l) : l[c.key]);

  function cell(c, l) {
    const v = colVal(c, l);
    switch (c.key) {
      case 'annual_budget': return fmtMoney(v);
      case 'prior_year_budget': return v == null ? h('span', { class: 'badge' }, 'new') : fmtMoney(v);
      case '_change': return l.annual_budget === 0 && l.prior_year_budget ? h('span', { class: 'badge' }, 'removed') : fmtSignedPct(v);
      case 'renewal_date': return fmtDate(v);
      case 'auto_renew': return v == null ? '–' : v ? 'Yes' : 'No';
      case 'category': return h('span', {}, h('span', { class: 'swatch sq', style: `background:${catColor(v)}` }), v);
      case 'owner': case 'cost_centre': return v || h('span', { class: 'badge warn' }, UNASSIGNED);
      default: return v == null ? '–' : String(v);
    }
  }

  function renderLines(lines) {
    const { key, dir } = state.sort;
    const col = COLS.find((c) => c.key === key) || COLS[7];
    const rows = [...lines].sort((a, b) => {
      const va = colVal(col, a), vb = colVal(col, b);
      if (va == null || va === '') return 1;
      if (vb == null || vb === '') return -1;
      return (typeof va === 'number' ? va - vb : String(va).localeCompare(String(vb))) * dir;
    });
    const total = sum(lines, (l) => l.annual_budget);
    const prior = sum(lines, (l) => l.prior_year_budget);
    $('line-count').textContent = `${lines.length} of ${DATA.lines.length} lines`;
    $('table-lines').replaceChildren(
      h('thead', {}, h('tr', {}, COLS.map((c) => h('th', { class: c.num ? 'num' : null, scope: 'col' },
        h('button', {
          type: 'button',
          'aria-sort': c.key === key ? (dir > 0 ? 'ascending' : 'descending') : 'none',
          onclick: () => { state.sort = { key: c.key, dir: c.key === key ? -dir : (c.num ? -1 : 1) }; renderLines(lines); },
        }, c.label))))),
      h('tbody', {}, rows.length ? rows.map((l) => h('tr', { class: l.annual_budget === 0 ? 'zero' : null, title: l.notes || null },
        COLS.map((c) => h('td', { class: c.num ? 'num' : null }, cell(c, l)))))
        : h('tr', {}, h('td', { colspan: COLS.length, class: 'empty' }, 'No lines match the filters.'))),
      h('tfoot', {}, h('tr', {},
        h('th', { colspan: 7, scope: 'row' }, `Total (${lines.length} lines)`),
        h('th', { class: 'num' }, fmtMoney(total)),
        h('th', { class: 'num' }, fmtMoney(prior)),
        h('th', { colspan: 3 }, ''))),
    );
  }

  function exportCsv() {
    const lines = DATA.lines.filter(matches);
    const months = ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'];
    const fields = ['line_id', 'vendor', 'product_or_service', 'category', 'cost_pool', 'tower', 'cost_centre', 'owner',
      'annual_budget', 'currency', 'capex_opex', 'contract_start', 'contract_end', 'renewal_date', 'auto_renew',
      'notice_period_days', 'notice_deadline', 'billing_frequency', 'licence_qty', 'unit_price', 'prior_year_budget', 'notes'];
    const esc = (v) => {
      if (v == null) return '';
      const str = typeof v === 'boolean' ? (v ? 'Y' : 'N') : String(v);
      return /[",\n]/.test(str) ? '"' + str.replace(/"/g, '""') + '"' : str;
    };
    const out = [fields.concat(months).join(',')];
    for (const l of lines) out.push(fields.map((f) => esc(l[f])).concat((l.monthly || []).map((v) => esc(Math.round(v * 100) / 100))).join(','));
    const blob = new Blob(['﻿' + out.join('\r\n')], { type: 'text/csv;charset=utf-8' });
    const a = h('a', { href: URL.createObjectURL(blob), download: `it-budget-FY${YEAR}-filtered.csv` });
    document.body.append(a);
    a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
  }

  // ------------------------------------------------------------------ data quality

  function renderQuality(lines) {
    const active = lines.filter((l) => l.annual_budget > 0);
    const total = sum(active, (l) => l.annual_budget);
    const share = (pred) => (total ? sum(active.filter(pred), (l) => l.annual_budget) / total : 0);
    const withRenewal = active.filter((l) => l.renewal_date);
    const metrics = [
      ['Budget with an owner', share((l) => l.owner)],
      ['Budget with a cost centre', share((l) => l.cost_centre)],
      ['Budget with a prior-year figure', share((l) => l.prior_year_budget != null)],
      ['Budget with monthly phasing provided', share((l) => !l.monthly_derived)],
      ['Renewals with a notice period', withRenewal.length ? withRenewal.filter((l) => l.notice_period_days != null).length / withRenewal.length : null],
    ];
    $('quality-metrics').replaceChildren(...metrics.map(([label, v]) => h('div', { class: 'hbar static' },
      h('span', { class: 'name', title: label }, label),
      h('span', { class: 'track' }, h('span', { class: 'fill', style: `width:${(v || 0) * 100}%;background:${v >= 0.95 ? 'var(--good)' : v >= 0.8 ? 'var(--urg-60)' : 'var(--bad)'}` })),
      h('span', { class: 'val' }, v == null ? '–' : fmtPct(v, 1)))));

    const ids = new Set(lines.map((l) => l.line_id));
    const issues = DATA.issues.filter((i) => !i.line_id || ids.has(i.line_id));
    $('quality-hint').textContent = `${issues.length} warning(s) for the filtered lines`;
    $('table-issues').replaceChildren(
      h('thead', {}, h('tr', {}, ['Row', 'Line', 'Field', 'Message'].map((c) => h('th', { scope: 'col' }, c)))),
      h('tbody', {}, issues.length ? issues.map((i) => h('tr', {},
        h('td', {}, i.row ?? ''), h('td', {}, i.line_id ?? ''), h('td', {}, i.field ?? ''), h('td', {}, i.message)))
        : h('tr', {}, h('td', { colspan: 4, class: 'empty' }, 'No warnings.'))),
    );
  }

  // ------------------------------------------------------------------ chrome

  function renderStatic() {
    $('budget-year').textContent = `FY${YEAR}`;
    $('cost-basis').textContent = `Annual budget in ${META.currency || 'n/a'}, as entered in the spreadsheet (no VAT, FX or inflation adjustments). Renewal urgency as of ${fmtDate(META.as_of)}.`;
    const built = new Date(META.generated_at);
    $('footer').replaceChildren(
      h('div', {}, 'Source: ', h('code', {}, META.source_file), ' · sha256 ', h('code', {}, (META.source_sha256 || '').slice(0, 12)),
        ` · built ${built.toLocaleString(LOCALE, { dateStyle: 'medium', timeStyle: 'short' })}`,
        ` · ${META.line_count} lines · ${META.warning_count} validation warning(s)`),
      /^sample/i.test(META.source_file || '') ? h('div', {}, 'Prototype: the sample data is fictional.') : null,
    );
    $('export-csv').addEventListener('click', exportCsv);

    const toggle = $('theme-toggle');
    const root = document.documentElement;
    try { const saved = localStorage.getItem('itbudget-theme'); if (saved) root.dataset.theme = saved; } catch (e) { /* ignore */ }
    toggle.addEventListener('click', () => {
      const dark = root.dataset.theme ? root.dataset.theme === 'dark' : matchMedia('(prefers-color-scheme: dark)').matches;
      root.dataset.theme = dark ? 'light' : 'dark';
      try { localStorage.setItem('itbudget-theme', root.dataset.theme); } catch (e) { /* ignore */ }
    });
  }

  function render() {
    hideTip();
    const lines = DATA.lines.filter(matches);
    writeHash();
    syncControls();
    renderKpis(lines);
    renderBars(lines);
    renderTimeline(lines);
    renderRenewalTable(lines);
    renderPhasing(lines);
    renderBridge(lines);
    renderLines(lines);
    renderQuality(lines);
  }

  readHash();
  renderStatic();
  buildFilterControls();
  addEventListener('hashchange', () => { state.f = {}; readHash(); render(); });
  render();

  // exposed for tests and for the next developer poking around in DevTools
  window.BudgetDashboard = { state, render, setFilter, computeBridge, urgencyOf };
})();
